//! The theme as typed constants: colour per theme and mode, design tokens, fonts. No dependencies.

/// An sRGB colour: its hex and its channels.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Colour {
    pub hex: &'static str,
    pub rgb: [u8; 3],
}

impl Colour {
    pub const fn new(hex: &'static str, r: u8, g: u8, b: u8) -> Self {
        Self {
            hex,
            rgb: [r, g, b],
        }
    }

    /// WCAG 2.x relative luminance.
    pub fn luminance(self) -> f64 {
        let lin = |c: u8| {
            let c = f64::from(c) / 255.0;
            if c <= 0.03928 {
                c / 12.92
            } else {
                ((c + 0.055) / 1.055).powf(2.4)
            }
        };
        0.2126 * lin(self.rgb[0]) + 0.7152 * lin(self.rgb[1]) + 0.0722 * lin(self.rgb[2])
    }

    /// WCAG 2.x contrast ratio against `other`, 1 to 21.
    pub fn contrast(self, other: Self) -> f64 {
        let (a, b) = (self.luminance(), other.luminance());
        let (hi, lo) = if a > b { (a, b) } else { (b, a) };
        (hi + 0.05) / (lo + 0.05)
    }
}

